        "description": "预计还需等待时间",
        "sampleValue": "18分钟"
      },
      "waitedDuration": {
        "type": "string",
        "description": "已经等待的时长",
        "sampleValue": "42分钟"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityName": {
              "type": "string",
              "description": "日历事件类别",
              "sampleValue": "calendar"
            },
            "entityId": {
              "type": "string",
              "description": "日程项唯一标识符",
              "sampleValue": "evt-orth-001"
            },
            "title": {
              "type": "string",
              "description": "预约科室日程标题",
              "sampleValue": "骨科复诊"
            },
            "dtStart": {
              "type": "string",
              "description": "预约科室日程开始时间",
              "sampleValue": "09:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "预约科室日程结束时间",
              "sampleValue": "09:50"
            },
            "eventLocation": {
              "type": "string",
              "description": "预约科室日程地点",
              "sampleValue": "门诊三楼"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": []
}

